parts(){return partList(this.groups.get(this.selected));}
setPart(id){if(id!==this.partId)this.clearIsolation();this.partId=id;this.select(this.selected);}
renderFrame(){if(this.realism)this.realism.render();else this.renderer.render(this.scene,this.camera);}
photoView(){this.setView('3d');this.host.closest('.stage')?.classList.add('photo-view');const bounds=new THREE.Box3();for(const g of this.groups.values())if(g.visible)bounds.expandByObject(g);if(bounds.isEmpty())return;const center=bounds.getCenter(new THREE.Vector3()),size=bounds.getSize(new THREE.Vector3());const distance=Math.max(size.y,size.x/this.camera.aspect)/(2*Math.tan(THREE.MathUtils.degToRad(this.camera.fov/2)))*1.28;this.controls.target.copy(center);this.camera.position.copy(center).add(new THREE.Vector3(distance*.28,distance*.16,distance));this.controls.update();this.dirty=true;}
snapshot(){this.dirty=true;const v=this.overlay.visible;this.overlay.visible=false;this.renderFrame();const image=this.renderer.domElement.toDataURL('image/png');this.overlay.visible=v;this.dirty=true;return image;}
exportOBJ(){const copy=new THREE.Group();for(const m of this.project.modules)if(m.visible)copy.add(buildModule(m));const hidden=[];copy.traverse(o=>{if(!o.visible)hidden.push(o);});for(const o of hidden)o.removeFromParent();try{return new OBJExporter().parse(copy);}finally{disposeGroup(copy);}}
thumbnail(m){if(!this.thumbRenderer){this.thumbRenderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});this.thumbRenderer.setSize(210,160);this.thumbRenderer.setPixelRatio(1);this.thumbRenderer.outputColorSpace=THREE.SRGBColorSpace;this.thumbRenderer.toneMapping=THREE.NeutralToneMapping;}if(!this.thumbEnvironment||this.thumbSource!==this.hdrSource){const pmrem=new THREE.PMREMGenerator(this.thumbRenderer);let env;if(this.hdrSource){env=pmrem.fromEquirectangular(this.hdrSource);}else{const room=new RoomEnvironment();env=pmrem.fromScene(room,.04);room.dispose();}this.thumbEnvironment?.dispose();this.thumbEnvironment=env;this.thumbSource=this.hdrSource;pmrem.dispose();}const scene=new THREE.Scene();scene.environment=this.thumbEnvironment.texture;scene.environmentIntensity=.85;scene.add(new THREE.HemisphereLight('#ffffff','#a2a68f',.25));const light=new THREE.DirectionalLight('#fff1e8',1.5);light.position.set(3,5,4);scene.add(light);const g=buildModule({...m,x:0,z:0,y:0,rotation:0});scene.add(g);const max=Math.max(m.width,m.height,m.depth)/1000,camera=new THREE.PerspectiveCamera(34,210/160,.01,30);camera.position.set(max*1.6,max*1.1,max*2);camera.lookAt(0,m.height/2100,0);this.thumbRenderer.render(scene,camera);const image=this.thumbRenderer.domElement.toDataURL();disposeGroup(g);return image;}
